CREATE TABLE IF NOT EXISTS owner (id boolean PRIMARY KEY DEFAULT true CHECK (id), email text NOT NULL, password_hash text NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token_hash bytea PRIMARY KEY, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS clients (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, name text NOT NULL, email text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', address text NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS projects (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, client_id bigint NOT NULL REFERENCES clients(id), name text NOT NULL, address text NOT NULL DEFAULT '', description text NOT NULL DEFAULT '', installation_type text NOT NULL DEFAULT '', supply_type text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'pendiente' CHECK(status IN ('pendiente','en ejecución','finalizada')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS boards (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, project_id bigint NOT NULL REFERENCES projects(id) ON DELETE CASCADE, name text NOT NULL);
CREATE TABLE IF NOT EXISTS circuits (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, board_id bigint NOT NULL REFERENCES boards(id) ON DELETE CASCADE, identifier text NOT NULL, description text NOT NULL DEFAULT '', circuit_type text NOT NULL DEFAULT '', power_w numeric NOT NULL CHECK(power_w >= 0), voltage_v numeric NOT NULL CHECK(voltage_v > 0), protection text NOT NULL, conductor_mm2 numeric NOT NULL CHECK(conductor_mm2 > 0), length_m numeric NOT NULL CHECK(length_m >= 0), UNIQUE(board_id,identifier));
CREATE TABLE IF NOT EXISTS materials (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, name text NOT NULL, category text NOT NULL DEFAULT '', unit text NOT NULL, price_cents bigint NOT NULL CHECK(price_cents >= 0));
CREATE TABLE IF NOT EXISTS project_materials (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, project_id bigint NOT NULL REFERENCES projects(id) ON DELETE CASCADE, material_id bigint NOT NULL REFERENCES materials(id), quantity numeric(12,3) NOT NULL CHECK(quantity > 0), UNIQUE(project_id,material_id));
CREATE TABLE IF NOT EXISTS quotations (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, project_id bigint NOT NULL REFERENCES projects(id), version int NOT NULL, status text NOT NULL DEFAULT 'borrador', labor_cents bigint NOT NULL CHECK(labor_cents >= 0), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id,version));
CREATE TABLE IF NOT EXISTS quotation_items (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, quotation_id bigint NOT NULL REFERENCES quotations(id) ON DELETE CASCADE, name text NOT NULL, unit text NOT NULL, quantity numeric(12,3) NOT NULL, price_cents bigint NOT NULL, total_cents bigint NOT NULL);
CREATE TABLE IF NOT EXISTS activities (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, project_id bigint NOT NULL REFERENCES projects(id) ON DELETE CASCADE, description text NOT NULL, observation text NOT NULL DEFAULT '', occurred_on date NOT NULL);
